package io.github.reiko45.galacticraft.registry;

import io.github.reiko45.galacticraft.GalacticraftCore;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.damagesource.DamageType;
import net.minecraft.world.level.Level;

/** Damage types (data-driven since 1.19.4; generated by GCWorldgenProvider). */
public final class GCDamageTypes {
    /** 1.12.2 DamageSourceGC.oxygenSuffocation: bypasses armour, absolute. Death message "%1$s ran out of oxygen!". */
    public static final ResourceKey<DamageType> OXYGEN_SUFFOCATION = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("oxygen_suffocation"));

    /** 1.12.2 DamageSourceGC.spaceshipCrash: "%1$s was in a spaceship crash!". */
    public static final ResourceKey<DamageType> SPACESHIP_CRASH = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("spaceship_crash"));

    /** 1.12.2 EntitySlimeling#attackEntityAsMob: new EntityDamageSource("slimeling", slimeling). */
    public static final ResourceKey<DamageType> SLIMELING = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("slimeling"));

    /** 1.12.2 DamageSourceGC.thermal: bypasses armour, absolute. "%1$s forgot thermal protection". */
    public static final ResourceKey<DamageType> THERMAL = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("thermal"));

    /** 1.12.2 DamageSourceGC.acid ("sulphuric_acid"): armour helps. "%1$s dissolved in sulphuric acid!". */
    public static final ResourceKey<DamageType> SULPHURIC_ACID = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("sulphuric_acid"));
    /** 1.12.2 EntityDamageSourceIndirect("meteor_chunk"), a projectile. */
    public static final ResourceKey<DamageType> METEOR_CHUNK = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("meteor_chunk"));
    /** 1.12.2 DamageSourceGC.laserTurret. */
    public static final ResourceKey<DamageType> LASER_TURRET = ResourceKey.create(Registries.DAMAGE_TYPE, GalacticraftCore.id("laser_turret"));

    private GCDamageTypes() {
    }

    public static DamageSource slimeling(net.minecraft.world.entity.Entity slimeling) {
        return slimeling.level().damageSources().source(SLIMELING, slimeling);
    }

    public static DamageSource crash(Level level) {
        return level.damageSources().source(SPACESHIP_CRASH);
    }

    public static DamageSource acid(Level level) {
        return level.damageSources().source(SULPHURIC_ACID);
    }

    public static DamageSource thermal(Level level) {
        return level.damageSources().source(THERMAL);
    }

    public static DamageSource suffocation(Level level) {
        return level.damageSources().source(OXYGEN_SUFFOCATION);
    }
}
